function DMain.prototype.talentHelp(self, path)
    self:bindMouse(
        path,
        function()
            local ui = self:getUI(path)
            local params = {
                x = ui:get_absolute_x() - 100,
                y = ui:get_absolute_y() + 30,
                playerId = LOCAL.PLAYER_ID
            }
            dialogs:show(DSelfTalentInfo, params)
        end,
        function()
            dialogs:hide(DSelfTalentInfo)
        end
    )
end
function DMain.prototype.equipHelp(self, path, idx)
    self:bindMouse(
        path,
        function()
            local ui = self:getUI(path)
            local list = LOCAL.PLAYER_DATA:getAll(EquipData)
            if #list <= idx then
                return
            end
            local params = {
                x = ui:get_absolute_x() - 160,
                y = ui:get_absolute_y(),
                skillId = list[idx + 1].configId
            }
            if dialogs:isShowed(DEquipInfo) then
                dialogs:get(DEquipInfo).data.params = params
                return
            end
            dialogs:show(DEquipInfo, params)
        end,
        function()
            dialogs:hide(DEquipInfo)
        end
    )
end
function DMain.prototype.attrHelp(self, path, id)
    self:bindMouse(
        path,
        function()
            local ui = self:getUI("BottomInfo.hero.info")
            dialogs:showRepeat(
                DHelpText,
                {
                    id = id,
                    x = ui:get_absolute_x() - 50,
                    y = ui:get_absolute_y() + ui:get_height() / 2 + 40
                }
            )
        end,
        function()
            dialogs:hide(DHelpText)
        end
    )
end
function DMain.prototype.genreHelp(self, path, getId)
    self:bindMouse(
        path,
        function()
            local ui = self:getUI("BottomInfo.hero.info")
            if getId(nil) == 0 then
                return
            end
            dialogs:showRepeat(
                DHelpGenre,
                {
                    genre = getId(nil),
                    x = ui:get_absolute_x() - 50,
                    y = ui:get_absolute_y() + ui:get_height() / 2 + 60
                }
            )
        end,
        function()
            dialogs:hide(DHelpGenre)
        end
    )
end
