        function()
            local playerData = LOCAL.PLAYER_DATA:getSingle(PlayerData)
            return "Lv." .. tostring(math.floor(playerData.level))
        end
    )
    self:watch(
        function()
            local player = LOCAL.PLAYER_DATA:getSingle(PlayerData)
            local maxLevel = roleLevelConfigList[#roleLevelConfigList]
            if maxLevel.level <= player.level then
                return {level = player.level, progress = 100}
            end
            local nextLevel = roleLevelConfigMap[player.level + 1]
            return {
                level = player.level,
                progress = math.min(
                    100,
                    math.max(0, player.exp / nextLevel.exp * 100)
                )
            }
        end,
        function(____, nVal, oVal)
            if oVal == nil then
                oVal = {level = 1, progress = 0}
            end
            if nVal.level == oVal.level and nVal.progress == oVal.progress then
                return
            end
            self:getUI("BottomInfo.exp.light"):set_visible(true)
            self:getUI("BottomInfo.exp.light"):play_ui_sequence(false, 0.01)
            if nVal.level == oVal.level then
                ProgressEffect:play(
                    self:getUI("BottomInfo.exp.progress"),
                    oVal.progress,
                    nVal.progress
                )
            else
                ProgressEffect:play(
                    self:getUI("BottomInfo.exp.progress"),
                    oVal.progress,
                    100
                )
                if nVal.level - oVal.level > 1 then
                    local count = nVal.level - oVal.level - 1
                    do
                        local index = 0
                        while index < count do
                            ProgressEffect:play(
                                self:getUI("BottomInfo.exp.progress"),
                                0,
                                100
                            )
                            index = index + 1
                        end
                    end
                end
                ProgressEffect:play(
                    self:getUI("BottomInfo.exp.progress"),
                    0,
                    nVal.progress
                )
            end
        end
    )
    ProgressEffect:play(
        self:getUI("BottomInfo.exp.progress"),
        0,
        0
    )
    UIEffect:play_opacity(
        self:getUI("BottomInfo.exp.progress_1.progress_bar_img"),
