    genreUtils:getRate()
end
function DMain.prototype.checkChooseGenre(self, idx)
    local playerData = datas.players[LOCAL.PLAYER_ID]:getSingle(PlayerData)
    local playerGenre = datas.players[LOCAL.PLAYER_ID]:getSingle(PlayerGenreData)
    local sel = playerGenre.canSelGenre[idx + 1]
    if playerData.gold < math.floor(sel.genre.money * (1 + playerData.cardBuy) + playerData.cardBuyValue + 0.5) then
        DTips:show(i18n["local"](i18n, "金币不足"))
        return
    end
    if playerGenre.canSelGenre == nil or #playerGenre.canSelGenre == 0 then
        console:error("选择流派技能异常1")
        return false
    end
    if idx >= 3 then
        console:error("选择流派技能异常2")
        return false
    end
    if playerGenre.canSelGenre[idx + 1].sellout then
        DTips:show(i18n["local"](i18n, "已购买"))
        return false
    end
    return true
end
function DMain.prototype.initMercenary(self)
    self:watch(
        function() return localData.main.showMercenary end,
        function(____, cur)
            if cur then
                GameAPI.stop_ui_comp_anim(LOCAL.PLAYER.handle, "1e74d623-6367-4c1a-9ae6-275e023352e6")
                GameAPI.play_ui_comp_anim_new(
                    LOCAL.PLAYER.handle,
                    "a045bf3b-4f63-4a1f-8232-d8113d97b379",
                    0,
                    nil,
                    1.5,
                    0
                )
                localData.main.showMercenarying = true
                self.mercenaryTimer = y3.ltimer.wait_frame(
                    10,
                    function()
                        localData.main.showMercenarying = false
                        self.mercenaryTimer:remove()
                        self.mercenaryTimer = nil
                    end
                )
            else
                if self.mercenaryTimer ~= nil then
                    self.mercenaryTimer:remove()
                    self.mercenaryTimer = nil
                end
                GameAPI.stop_ui_comp_anim(LOCAL.PLAYER.handle, "a045bf3b-4f63-4a1f-8232-d8113d97b379")
                GameAPI.play_ui_comp_anim_new(
                    LOCAL.PLAYER.handle,
                    "1e74d623-6367-4c1a-9ae6-275e023352e6",
                    0,
                    nil,
                    1.5,
                    0
                )
            end
        end,
        false,
        true
    )
    local gameData = datas.global:getSingle(GameData)
    self:watchOnce(
        function() return gameData.level == 7 end,
        function(____, v)
            if v then
                localData.main.mercenaryLevel = 2
            end
            return v
        end
    )
    self:watchOnce(
        function() return gameData.level == 13 end,
        function(____, v)
            if v then
                localData.main.mercenaryLevel = 3
            end
            return v
        end
    )
    self:watchOnce(
        function() return gameData.level == 19 end,
        function(____, v)
            if v then
                localData.main.mercenaryLevel = 4
            end
            return v
        end
    )
    self:watchOnce(
        function() return gameData.level == 25 end,
        function(____, v)
            if v then
                localData.main.mercenaryLevel = 5
            end
            return v
        end
    )
    self:bindVisible(
        "MercenaryList",
        function()
            return localData.main.showMercenary and not LOCAL.IS_OBSERVER
        end
    )
    self:bindVisible(
        "MercenaryList.list.lock",
        function()
            local gameData = datas.global:getSingle(GameData)
            return gameData.level < 1 + (localData.main.mercenaryLevel - 1) * 6
        end
    )
    self:bindText(
        "MercenaryList.list.lock.tips.content",
        function()
            return i18n:format("第#ff0000${level}#ffffff波解锁", {level = 1 + (localData.main.mercenaryLevel - 1) * 6})
        end
    )
    local list = {}
    do
        local index = 0
        while index < 5 do
            local level = index + 1
            local currentList = __TS__ArraySort(
                __TS__ArrayFilter(
                    mercenaryConfigList,
                    function(____, a) return a.rarity == level end
                ),
                function(____, a, b)
                    if a.showId == b.showId then
                        return a.id - b.id
                    end
                    return a.showId - b.showId
                end
            )
            list[#list + 1] = currentList
            self:bindAction(
                "MercenaryList.level.level_" .. tostring(level),
                "左键-点击",
                function()
                    localData.main.mercenaryLevel = level
                end
            )
            self:bindVisible(
                ("MercenaryList.level.level_" .. tostring(level)) .. ".select",
                function() return localData.main.mercenaryLevel == level end
            )
            self:bindVisible(
                ("MercenaryList.level.level_" .. tostring(level)) .. ".disable",
                function()
                    local gameData = datas.global:getSingle(GameData)
                    return gameData.level < 1 + (level - 1) * 6
                end
            )
            index = index + 1
        end
    end
    do
        local index = 0
        while index < 10 do
            local i = index
            local root = ""
            if index < 5 then
                root = "MercenaryList.list.list1.item_" .. tostring(index + 1)
            else
                root = "MercenaryList.list.list2.item_" .. tostring(index + 1)
            end
            self:bindVisible(
                root,
                function()
                    local item = list[localData.main.mercenaryLevel][i + 1]
                    return item ~= nil
                end
            )
            self:bindImage(
                root .. ".icon",
                function()
                    local item = list[localData.main.mercenaryLevel][i + 1]
                    return item and item.icon or 0
                end
            )
            self:bindAction(
                root,
                "左键-点击",
                function()
                    if not localData.main.showMercenary or localData.main.showMercenarying then
                        return
                    end
                    local item = list[localData.main.mercenaryLevel][i + 1]
                    if item == nil then
                        return
                    end
                    buildManager:buildQuickly(item.id)
                end,
                0.05
            )
            self:bindAction(
                root,
                "右键-点击",
                function()
                    if not localData.main.showMercenary or localData.main.showMercenarying then
                        return
                    end
                    local item = list[localData.main.mercenaryLevel][i + 1]
                    if item == nil then
                        return
                    end
                    buildManager:buildQuickly(item.id)
                end,
                0.05
            )
            do
                local t = 0
                while t < 9 do
                    local element = t + 1
                    self:bindVisible(
                        (root .. ".type") .. tostring(t + 1),
                        function()
                            local item = list[localData.main.mercenaryLevel][i + 1]
                            return (item and item.label) == element
                        end
                    )
                    t = t + 1
                end
            end
            local cost = self:compute(function()
                local item = list[localData.main.mercenaryLevel][i + 1]
                local playerData = LOCAL.PLAYER_DATA:getSingle(PlayerData)
                local price = item and item.price or 0
                local gameData = datas.global:getSingle(GameData)
                local totalPrice = price * (1 + playerData.mercenaryDiscard) + playerData.mercenaryDiscardValue
                if (gameData and gameData.randomEventType) == GameRandomEventType["佣兵狂潮"] then
                    totalPrice = math.floor(totalPrice * 0.5 + 0.5)
                else
                    totalPrice = math.floor(totalPrice + 0.5)
                end
                return totalPrice
            end)
            self:bindText(
                root .. ".cost.cost",
                function()
                    return tostring(cost.value)
                end
            )
            self:bindTextColor(
                root .. ".cost.cost",
                function()
                    local playerData = LOCAL.PLAYER_DATA:getSingle(PlayerData)
                    if playerData.wood >= cost.value then
                        return UIUtils:toColor("ffff00")
                    end
                    return UIUtils:toColor("ff0000")
                end
            )
            self:bindMouse(
                root,
                function()
                    if not localData.main.showMercenary or localData.main.showMercenarying then
                        return
                    end
                    local ui = self:getUI(root)
                    local ui2 = self:getUI("MercenaryList.left")
                    local item = list[localData.main.mercenaryLevel][i + 1]
                    local cfgId = item.id
                    local data = {
                        x = ui2:get_absolute_x(),
                        y = ui:get_absolute_y(),
                        cfgId = cfgId
                    }
                    dialogs:showRepeat(DInfoMercenary, data)
                end,
                function()
                    dialogs:hide(DInfoMercenary)
                end
            )
            index = index + 1
        end
    end
    self:watch(
        function()
            local gameData = datas.global:getSingle(GameData)
            return gameData.gameStatus == GameStatus["准备回合"]
        end,
        function(____, current, old)
            if current then
                buildManager:enter()
            else
                buildManager:exit()
            end
        end,
        false,
        true
    )
end
function DMain.prototype.initFarmer(self)
    local gameData = datas.global:getSingle(GameData)
    self:bindAction(
        "BottomInfo.farmerBtn",
        "左键-点击",
        function()
            if gameData.level < 3 or gameData.level == 3 and gameData.gameStatus == GameStatus["准备回合"] then
                return
            end
            if not farmerManager:checkLevelUp(LOCAL.PLAYER_ID) then
                return
            end
            if localData.guide == GuideProgress.Guide_4_2 then
                localData.guide = GuideProgress.Guide_4_3
            end
            SoundManager:play(SoundType["升级科技成功"])
            technologyController.levelUp:execute(LOCAL.PLAYER_ID)
        end
    )
    self:bindText(
        "BottomInfo.farmerBtn.normal.title",
        function()
            if farmerManager:isMaxLevel(LOCAL.PLAYER_ID) then
                return i18n["local"](i18n, "科技满级")
            end
            return i18n["local"](i18n, "科技提升")
        end
    )
    self:bindVisible(
        "BottomInfo.farmerBtn.select",
        function()
            if gameData.level < 3 or gameData.level == 3 and gameData.gameStatus == GameStatus["准备回合"] then
                return false
            end
            return farmerManager:checkLevelUp(LOCAL.PLAYER_ID, false) and not localData.main.technologyIng
        end
    )
    self:bindVisible(
        "BottomInfo.farmerBtn.disable",
        function()
            if gameData.level < 3 or gameData.level == 3 and gameData.gameStatus == GameStatus["准备回合"] then
                return true
            end
            return localData.main.technologyIng
