function DMain.prototype.initBuffList(self)
    local BUFF_MAX_QUANTITY = 14
    do
        local i = 0
        while i < BUFF_MAX_QUANTITY do
            self.buffList.value[i + 1] = {
                visible = false,
                name = "",
                des = "",
                icon = 0,
                quantity = nil,
                createTime = 0,
                duration = nil,
                debuff = false,
                pauseTime = -1
            }
            i = i + 1
        end
    end
    local function refreshData(____, data, v, config)
        data.visible = true
        if config.showName.value ~= data.name then
            data.name = config.showName.value
        end
        if config.describe.value ~= data.des then
            data.des = config.describe.value
        end
        if config.icon ~= data.icon then
            data.icon = config.icon
        end
        if config.uiDisplay[1] == 1 then
            local id = config.uiDisplay[2]
            local a = v.owner:v(id)
            if data.quantity ~= a then
                data.quantity = a
            end
        elseif config.uiDisplay[1] == 2 then
            local id = config.uiDisplay[2]
            local a = v.owner:p(id)
            if data.quantity ~= a then
                data.quantity = a
            end
        elseif config.uiDisplay[1] == 3 then
            local id = config.uiDisplay[2]
            local a = v:s(id)
            if data.quantity ~= a then
                data.quantity = a
            end
        else
            if data.quantity ~= v.activeData.quantity then
                data.quantity = (config.overlay == 3 or config.overlay == 4 or config.overlay == 5) and v.activeData.quantity or nil
            end
        end
        if config.uitime ~= data.duration then
            data.duration = config.uitime ~= 0 and config.uitime or nil
        end
        local isDebuff = __TS__ArrayIndexOf(config.group, 20) ~= -1
        if data.debuff ~= isDebuff then
            data.debuff = isDebuff
        end
        if data.pauseTime ~= -1 and not v.owner.activeData.pauseTimer then
            local dx = data.pauseTime - data.createTime
            data.createTime = global.time.value - dx
            data.pauseTime = -1
        end
        if v.birthday ~= data.createTime then
            data.createTime = v.birthday
            data.pauseTime = -1
        end
        data.pauseTime = data.pauseTime == -1 and v.owner.activeData.pauseTimer and global.time.value or data.pauseTime
    end
    y3.ltimer.loop_frame(
        1,
        function()
            local unit = datas.players[LOCAL.PLAYER_ID]:getSingle(UnitData)
            local g = unit.entity.effectsGroup[21]
            if not g then
                return
            end
            local i = 0
            local j = 0
            for k in pairs(g) do
                j = j + 1
                if j > BUFF_MAX_QUANTITY then
                    break
                end
                local ____self_buffList_value_74 = self.buffList.value
                local ____i_73 = i
                i = ____i_73 + 1
                local data = ____self_buffList_value_74[____i_73 + 1]
                local v = g[k]
                if v.id ~= nil then
                    local config = v.config
                    refreshData(nil, data, v, config)
                else
                    for ____, buff in ipairs(v) do
                        local config = buff.config
                        refreshData(nil, data, buff, config)
                    end
                end
            end
            do
                local k = i
                while k < BUFF_MAX_QUANTITY do
                    local ____self_buffList_value_76 = self.buffList.value
                    local ____i_75 = i
                    i = ____i_75 + 1
                    local data = ____self_buffList_value_76[____i_75 + 1]
                    data.visible = false
                    k = k + 1
                end
            end
        end
    )
    do
        local i = 0
        while i < BUFF_MAX_QUANTITY do
            local index = i
            local root = "buffList.buff_" .. tostring(i + 1)
            local iconPath = root .. ".buff.icon"
            local progressPath = root .. ".buff.progress"
            local progressImagePath = root .. ".buff.progress.progress_bar_img"
            local quantityPath = root .. ".buff.quantity"
            local data = self.buffList.value[index + 1]
            self:bindVisible(
                root,
                function()
                    return data.visible
                end
            )
            self:bindImage(
                iconPath,
                function()
                    return data.icon
                end
            )
            self:bindProgress(
                progressPath,
                function()
                    if data.visible == false or data.duration == nil then
                        return 0
                    end
                    return data.pauseTime == -1 and 100 - (global.time.value - data.createTime) / data.duration * 100 % 100 or 100 - (data.pauseTime - data.createTime) / data.duration * 100 % 100
                end
            )
            self:bindText(
                quantityPath,
                function()
                    return tostring(data.quantity or "")
                end
            )
            self:bindAction(
                root,
                "鼠标-移入",
                function(____, ui, p)
                    local x = ui:get_absolute_x()
                    local y = ui:get_absolute_y()
                    dialogs:show(
                        DBuffInfo,
                        {
                            x = x,
                            y = y + ui:get_real_height(),
                            name = data.name,
                            des = data.des,
                            icon = data.icon
                        }
                    )
                end
            )
            self:bindAction(
                root,
                "鼠标-移出",
                function()
                    dialogs:hide(DBuffInfo)
                end
            )
            i = i + 1
        end
    end
end
